    def rounded(n, mode):
        return (n + 5000) // 10000 if mode == "half_up" else n // 10000

    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        chosen = {}
        for pos, event in enumerate(data["events"]):
            seq = event.get("sequence", 0)
            if seq > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(pos))
            key = ((seq, event.get("revision", 0), pos) if sequence_first
                   else (event.get("revision", 0), pos))
            if event_id not in chosen or key > chosen[event_id][0]:
                chosen[event_id] = (key, event)

        balances = dict(data.get("opening", {}))
        mode = data["rounding"]
        for _, event in chosen.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount), mode)
            base = net if discounted else raw
            tax = rounded(base * event.get("tax_bp", 0), mode)
            total = net + tax
            if event.get("kind") == "refund":
                total = -total
            key = event.get("account", "default") + "|" + event.get("currency", "USD")
            balances[key] = balances.get(key, 0) + total
        return {"balances": balances}
    return solve


def _resolver():
    from itertools import product

    def solve(data):
        packages = data["packages"]
        names = sorted(packages)
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        roots = data["roots"]
        domains = [[-1] + sorted(row["version"] for row in packages[name])
                   for name in names]
        rows_by_version = {name: {row["version"]: row for row in rows}
                           for name, rows in packages.items()}

        for vector in product(*domains):
            selected = {name: version for name, version in zip(names, vector)
                        if version != -1}
            if any(name not in selected or not low <= selected[name] <= high
                   for name, (low, high) in roots.items()):
                continue
            if any(name in selected and
                   (selected[name] in blocked.get(name, []) or
                    (name in pins and selected[name] != pins[name]))
                   for name in names):
                continue

            edges = {name: [] for name in selected}
            closure = set(roots)
            pending = list(roots)
            valid = True
            while pending and valid:
                name = pending.pop()
                if name not in selected:
                    valid = False
                    break
                row = rows_by_version[name][selected[name]]
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    other = dep["name"]
                    version = selected.get(other, -1)
                    if version == -1 or not dep["min"] <= version <= dep["max"]:
                        valid = False
                        break
                    edges[name].append(other)
                    if other not in closure:
                        closure.add(other)
                        pending.append(other)
            if not valid or closure != set(selected):
                continue

            finished, active = set(), set()
            def visit(name):
                if name in active:
                    return False
                if name in finished:
                    return True
                active.add(name)
                if any(not visit(other) for other in edges[name]):
                    return False
                active.remove(name)
                finished.add(name)
                return True
            if all(visit(name) for name in selected):
                return {"versions": selected}
        return {"error": "unsatisfiable"}
    return solve


def _schedule():
    from collections import Counter
    from itertools import combinations

    def solve(data):
        jobs = data["jobs"]
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        best_ids = None
        best_value = None
        for subset in combinations(jobs, k):
            ids = {job["id"] for job in subset}
            if ids & blocked or not mandatory <= ids:
                continue
            counts = Counter(job["group"] for job in subset)
            if any(not low <= counts[group] <= high
                   for group, (low, high) in quotas.items()):
                continue
            ordered = sorted(subset, key=lambda job: (job["start"], job["end"]))
            end = -1
            compatible = True
            for job in ordered:
                if job["start"] < end:
                    compatible = False
                    break
                end = job["end"]
            if not compatible:
                continue
            selected = sorted(ids)
            value = sum(job["value"] for job in subset)
            if (best_value is None or value > best_value or
                    (value == best_value and selected < best_ids)):
                best_value, best_ids = value, selected
        if best_ids is None:
            return {"error": "impossible"}
        return {"selected": best_ids, "value": best_value}
    return solve


def _routes():
    import heapq

    def solve(data):
        required = data.get("required", [])
        bit = {node: 1 << i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        start_node = data["source"]
        start_mask = bit.get(start_node, 0)
        start_state = (start_node, start_mask, data["coupons"])
        distances = {start_state: data["start"]}
        queue = [(data["start"], start_node, start_mask, data["coupons"])]
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        while queue:
            time, node, mask, remaining = heapq.heappop(queue)
            state = (node, mask, remaining)
            if distances.get(state) != time:
                continue
            if node == data["target"] and mask == full and remaining == 0:
                return {"arrival": time}
            for edge in graph[node]:
                depart = max(time, edge["open"])
                if depart >= edge["close"]:
                    continue
                durations = [edge["duration"]]
                if remaining:
                    durations.append(max(2, edge["duration"] - edge.get("discount", 0)))
                for choice, duration in enumerate(durations):
                    next_time = depart + duration
                    if next_time > data["deadline"]:
                        continue
                    left = remaining - (1 if choice == 1 else 0)
                    next_node = edge["v"]
                    next_mask = mask | bit.get(next_node, 0)
                    next_state = (next_node, next_mask, left)
                    if next_time < distances.get(next_state, float("inf")):
                        distances[next_state] = next_time
                        heapq.heappush(queue, (next_time, next_node, next_mask, left))
        return {"arrival": None}
    return solve


